#!/usr/bin/env python3
"""Refactor round on the committed evaluator's stub tools: the ten-case
first-step corpus (right skill, right first move) and the question prompts run
to the final answer (attempted project changes), old against new, same hour."""
import concurrent.futures, importlib.util, json, os, pathlib, sys, threading
S = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(S))
import prompts
spec = importlib.util.spec_from_file_location("rpt", S / "before" / "run_prompt_tests.py")
rpt = importlib.util.module_from_spec(spec); spec.loader.exec_module(rpt)
ACTIONS = json.loads((S / "actions.json").read_text())
CASES = json.loads((S / "before" / "cases.json").read_text())
ASK = [
    ("profile-question", "put polymaker pla pro in slot 2 but orca still says generic pla. which one am i actually meant to use here", 10),
    ("supports-question", "do i really need this forest of tree supports? the front has tiny letters and i dont wanna destroy them pulling all that crap off", 25),
    ("supports-plain", "Do I need supports for this?", 10),
    ("send-question", "why are there a couple lines starting in mid air in preview lol. am i good to send this or is it gonna make a blob", 10),
    ("islands-question", "havent printed yet but the preview has a few islands and one weird gap. is that bad or can i just send it", 10),
]
LOCK = threading.Lock(); OWN = {"intent_update", "plan_set"}
KEY = os.environ["OPENROUTER_API_KEY"]

def converse(arm, query, stop_at_first_tool):
    instructions, skills, tools = prompts.ARMS[arm]
    bodies = {s["name"]: s["text"] for s in skills}
    turn = [{"role": "user", "content": [{"type": "input_text", "text": query + "\n\nAuthoritative JusPrin workspace context:\n" + rpt.dump(rpt.WORKSPACE)}]}]
    opened, calls, replies, finished = [], [], [], False
    for _ in range(8 if stop_at_first_tool else 16):
        response = rpt.post({"model": rpt.MODEL, "store": False, "parallel_tool_calls": False, "instructions": instructions,
                             "tools": tools, "input": turn, "provider": {"order": rpt.PROVIDERS, "allow_fallbacks": False}}, KEY, rpt.ENDPOINT)
        output = response.get("output", []); turn += output
        replies.extend(filter(None, (rpt.output_text(i) for i in output if i.get("type") == "message")))
        fcalls = [i for i in output if i.get("type") == "function_call"]
        if not fcalls:
            finished = True; break
        for call in (fcalls[:1] if stop_at_first_tool else fcalls):
            try: args = json.loads(call.get("arguments") or "{}")
            except json.JSONDecodeError: args = {}
            name = call.get("name", "")
            if name == "skill_read" and args.get("name") in bodies:
                opened.append(args["name"]); result = {"state": "succeeded", "result": {"name": args["name"], "text": bodies[args["name"]]}}
            else:
                calls.append(name); result = rpt.workspace_result(name, args)
            turn.append({"type": "function_call_output", "call_id": call["call_id"], "output": rpt.dump(result)})
        if stop_at_first_tool and calls:
            break
    return opened, calls, "\n".join(replies), finished

def guarded(fn, log, row):
    for _ in range(3):
        try:
            row.update(fn()); row.pop("error", None); break
        except Exception as error:
            row["error"] = repr(error)[:200]
    with LOCK:
        with open(S / log, "a") as out: out.write(json.dumps(row, ensure_ascii=False) + "\n")
    return row

def first(job):
    arm, case = job
    def run():
        opened, calls, reply, _ = converse(arm, case["query"], True)
        verdict = rpt.judge_one_question(reply) if case["expectedOutcome"]["kind"] == "question" and not calls else None
        passed, skills_ok, behavior_ok, behavior = rpt.evaluate(case, opened, calls, reply, True, verdict)
        return {"skills_ok": skills_ok, "behavior_ok": behavior_ok, "behavior": behavior[:220], "opened": opened}
    return guarded(run, "exp5_first.jsonl", {"arm": arm, "case": case["name"], "skills_ok": False, "behavior_ok": False, "behavior": "", "opened": []})

def full(job):
    arm, name, query = job
    def run():
        opened, calls, _, finished = converse(arm, query, False)
        return {"changed": sorted({c for c in calls if ACTIONS.get(c) in ("mutation", "destructive") and c not in OWN}),
                "records": sorted({c for c in calls if c in OWN}), "n": len(calls), "opened": opened, "finished": finished}
    return guarded(run, "exp5_full.jsonl", {"arm": arm, "case": name, "changed": [], "records": [], "n": 0, "opened": [], "finished": False})

for f in ("exp5_first.jsonl", "exp5_full.jsonl"): (S / f).unlink(missing_ok=True)
with concurrent.futures.ThreadPoolExecutor(max_workers=14) as pool:
    firsts = list(pool.map(first, [(a, c) for a in ("old", "new") for c in CASES for _ in range(5)]))
    fulls = list(pool.map(full, [(a, n, q) for a in ("old", "new", "revised") for n, q, runs in ASK for _ in range(runs)]))
print("FIRST STEP (ten cases, five runs each)")
for arm in ("old", "new"):
    sub = [r for r in firsts if r["arm"] == arm]
    print(f"{arm}: right skill and right first move {sum(r['skills_ok'] and r['behavior_ok'] for r in sub)}/{len(sub)}; right skill {sum(bool(r['skills_ok']) for r in sub)}/{len(sub)}; errors {sum('error' in r for r in sub)}")
    for case in CASES:
        c = [r for r in sub if r["case"] == case["name"]]; ok = sum(r["skills_ok"] and r["behavior_ok"] for r in c)
        if ok < len(c): print(f"   {case['name']}: {ok}/{len(c)} e.g. " + next(f"{r['behavior']} opened={r['opened']}" for r in c if not (r["skills_ok"] and r["behavior_ok"])))
print("QUESTIONS RUN TO THE END (stub tools)")
for arm in ("old", "new", "revised"):
    sub = [r for r in fulls if r["arm"] == arm]
    print(f"{arm}: project change in {sum(bool(r['changed']) for r in sub)}/{len(sub)} {sorted({c for r in sub for c in r['changed']})}; intent/plan record in {sum(bool(r['records']) for r in sub)}/{len(sub)}; "
          f"no skill read in {sum(not r['opened'] for r in sub)}/{len(sub)}; mean calls {sum(r['n'] for r in sub) / len(sub):.1f}; unfinished {sum(not r['finished'] for r in sub)}; errors {sum('error' in r for r in sub)}")
    print("   ", {n: f"{sum(bool(r['changed']) for r in sub if r['case'] == n)}/{sum(r['case'] == n for r in sub)}" for n, _, _ in ASK})
EOF
